input.sparql:
SELECT ?e ?name ?sensor WHERE {
  ?s a brick:PowerSensor .
  ?s brick:hasParent ?e .
  ?e rdfs:label ?name .
} LIMIT 50

SELECT ?s ?e ?ref ?ts WHERE {
  ?s a brick:Power_Sensor .
  ?s brick:hasParent ?e .
  OPTIONAL { ?s ref:hasExternalReference ?ref . ?ref ref:hasTimeseriesId ?ts . }
}

SELECT ?ps ?sensor ?e ?ref ?ts WHERE {
  ?ps a brick:Power_Sensor .
  ?sensor a brick:Sensor .
  FILTER(STR(?ps) = STR(?sensor))
  ?sensor brick:hasParent ?e .
  OPTIONAL { ?sensor ref:hasExternalReference ?ref . }
  OPTIONAL { ?ref ref:hasTimeseriesId ?ts . }
}

SELECT ?sensor ?cls ?parent WHERE {
  ?sensor a ?cls .
  VALUES ?cls { brick:Electric_Power_Sensor brick:Power_Sensor brick:Heating_Thermal_Power_Sensor }
  ?sensor brick:hasParent ?parent .
}

SELECT ?sensor ?p ?x WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor ?p ?x . FILTER(?p != rdf:type)
} LIMIT 60
